package us.dannyhand.ipabackup

import org.junit.Assert.assertArrayEquals
import org.junit.Assert.assertEquals
import org.junit.Test
import us.dannyhand.ipabackup.plist.BinaryPlist
import java.util.Base64
import java.util.Date

/** Fixtures generated with Python plistlib (FMT_BINARY). */
class BinaryPlistTest {
    private fun load(b64: String) = BinaryPlist.parse(Base64.getDecoder().decode(b64))

    @Suppress("UNCHECKED_CAST")
    @Test
    fun installationProxyStyleReply() {
        val r = load("") as Map<String, Any?>
        assertEquals("BrowsingApplications", r["Status"])
        assertEquals(120L, r["Total"])
        val list = r["CurrentList"] as List<Map<String, Any?>>
        assertEquals(120, list.size)
        assertEquals("com.example.app0", list[0]["CFBundleIdentifier"])
        assertEquals(1234567890123L, list[0]["StaticDiskUsage"])
        assertEquals("Café Ünïcode 游戏", list[3]["CFBundleDisplayName"])
        assertEquals("1.119", list[119]["CFBundleShortVersionString"])
    }

    @Suppress("UNCHECKED_CAST")
    @Test
    fun allTypes() {
        val m = load("") as Map<String, Any?>
        assertEquals(true, m["t"]); assertEquals(false, m["f"])
        assertEquals(-5L, m["neg"]); assertEquals(3.5, m["real"])
        assertArrayEquals(byteArrayOf(0, 1, 2) + "hello".toByteArray(), m["data"] as ByteArray)
        assertEquals(Date(1356998400000L), m["date"])
        assertEquals(emptyList<Any>(), m["empty"])
        assertEquals("x".repeat(40), m["long"])
        val nested = (m["nested"] as Map<String, Any?>)["a"] as List<Any?>
        assertEquals(1L, nested[0])
        assertEquals("c", ((nested[1] as List<Any?>)[1] as Map<String, Any?>)["b"])
    }
}
